  $out = New-Object System.IO.MemoryStream; $ds.CopyTo($out)
  return $out.ToArray()
}
function TreeLookup($treeSha, $name) {
  $b = InflateBytes $treeSha
  $nul = [Array]::IndexOf($b, [byte]0)
  $pos = $nul + 1
  while ($pos -lt $b.Length - 20) {
    $nul2 = [Array]::IndexOf($b, [byte]0, $pos)
    if ($nul2 -lt 0 -or ($nul2 + 21) -gt $b.Length) { break }
    $metaBytes = New-Object byte[] ($nul2 - $pos)
    [Array]::Copy($b, $pos, $metaBytes, 0, $metaBytes.Length)
    $meta = [System.Text.Encoding]::ASCII.GetString($metaBytes)
    $nm = $meta.Split(' ')[1]
    if ($nm -eq $name) {
      $raw = New-Object byte[] 20
      [Array]::Copy($b, $nul2 + 1, $raw, 0, 20)
      return @($meta.Split(' ')[0], ([BitConverter]::ToString($raw) -replace '-',''))
    }
    $pos = $nul2 + 21
  }
  return $null
}
function Descend($treeSha, $parts) {
  $cur = $treeSha
  for ($i=0; $i -lt $parts.Length; $i++) {
    $e = TreeLookup $cur $parts[$i]
    if ($null -eq $e) { return "MISSING: " + ($parts[0..$i] -join '/') }
    if ($i -eq $parts.Length - 1) { return ("{0} {1}" -f $e[0], $e[1]) }
    $cur = $e[1]
  }
}
